CREATE TABLE player (
                        "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                        "username" VARCHAR(50) UNIQUE NOT NULL,
                        "email" VARCHAR(100) UNIQUE NOT NULL,
                        "password_hash" VARCHAR(255) NOT NULL,
                        "created_at" timestamptz NOT NULL DEFAULT (now()),
                        "updated_at" timestamptz NOT NULL DEFAULT (now()),
                        "is_banned" BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE character_instance (
                                    "id" uuid PRIMARY KEY,
                                    "profile_id" bigint NOT NULL,
                                    "character_def_id" bigint NOT NULL,
                                    "level" INT NOT NULL DEFAULT 1 CHECK (level >= 1),
                                    "exp" int NOT NULL DEFAULT 0 CHECK (exp >= 0)
);

CREATE TABLE profile (
                         "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                         "player_id" bigint NOT NULL,
                         "name" VARCHAR(100) NOT NULL,
                         "level" int NOT NULL DEFAULT 1 CHECK (level >= 1),
                         "exp" int NOT NULL DEFAULT 0 CHECK (exp >= 0)
);

CREATE TABLE character_inventory (
                                     "id" uuid PRIMARY KEY,
                                     "character_id" uuid NOT NULL,
                                     "item_def_id" bigint NOT NULL,
                                     "quantity" INT NOT NULL CHECK (quantity > 0),
                                     "meta" jsonb
);

CREATE TABLE profile_inventory (
                                   "id" SERIAL PRIMARY KEY,
                                   "profile_id" bigint NOT NULL,
                                   "item_def_id" bigint NOT NULL,
                                   "quantity" int NOT NULL CHECK (quantity > 0),
                                   "meta" jsonb
);

ALTER TABLE character_inventory ADD FOREIGN KEY ("character_id") REFERENCES character_instance ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE profile ADD FOREIGN KEY ("player_id") REFERENCES player ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE character_instance ADD FOREIGN KEY ("profile_id") REFERENCES profile ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE profile_inventory ADD FOREIGN KEY ("profile_id") REFERENCES profile ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

CREATE INDEX idx_profile_player_id
    ON profile (player_id);

CREATE INDEX idx_character_instance_profile_id
    ON character_instance (profile_id);

CREATE INDEX idx_profile_inventory_profile_id
    ON profile_inventory (profile_id);

CREATE INDEX idx_character_inventory_character_id
    ON character_inventory (character_id);